raw:
{
  "spells": [
    {
      "id": "spell_earth_10",
      "theory": "承重纹把魔力送进墙体表层，沿石缝与砖缝形成一张极薄的感应脉络。脉络不改变砖石本身，只把某处受力异常转化为纹路中轻微的阻滞感。施术者以手贴墙时，异常处会像逆着细流推掌，提示该段可能开裂或下沉。纹路无法撑住墙体，也不能补上缺失的灰浆。",
      "casting": "单掌贴墙，另一手食指沿水平方向缓慢划出三道平行短线，每划一道停一息。三道线都完整后才能读取阻滞感。",
      "failure": "若划得过快，纹路会在墙表散成模糊的暗痕，约一刻钟后自行消退。此时贴墙只能感到均匀的凉意，无法分辨异常位置，还可能把旧裂缝误判为承重问题。",
      "counters": [
        "在墙表涂一层厚灰泥，可暂时隔断纹路与砖缝的接触。",
        "用湿布反复擦拭划线处，能提前抹去感应脉络。"
      ],
      "socialConsequences": "河谷乡约常请施术者查看谷仓与堤岸小屋的墙体，以决定是否推迟存粮。石匠担心外行凭一次感应就要求拆墙，坏了他们的工期与名声。城中公会则要求施术者只报告异常位置，不得替屋主决定修缮方案；若把感应结果卖给两家竞争工匠，会被视为挑拨。港务对货栈墙体另有登记，施术者须把结果交给仓管而非直接改动货架。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时阻滞感很弱，需反复贴墙才能确认大致区段。",
        "熟练后能沿纹路指出异常所在的那道砖缝。",
        "再进一步可分辨异常是缓慢发展还是已经稳定。",
        "高熟练者读取更快，仍只提示受力异常，不修复墙体。"
      ]
    },
    {
      "id": "spell_earth_11",
      "theory": "石肤术把魔力压进受术者皮肤与衣料之间的薄层，使这层变得像干燥的硬泥壳。外力撞上时，泥壳先分散冲击，再传给身体，因此抗撞击提高，但关节活动会被泥壳牵住。泥壳不透气，也不防利刃切割。它不改变骨骼，也不能让受术者搬动更重的东西。",
      "casting": "施术者以拇指按住受术者肩头，另一手在其手臂外侧画一个方形，四边各停一息。方形闭合后，泥色从肩向四肢蔓延。",
      "failure": "方形若画歪，泥色会集中在一侧，使受术者转身时明显发僵。约一刻钟后泥壳碎成干屑脱落，皮肤留一层灰痕，抗撞击效果也随之消失。",
      "counters": [
        "用大量清水浸透泥壳，可使其提前开裂脱落。",
        "以利刃沿泥壳接缝处划开，能局部解除硬化。"
      ],
      "socialConsequences": "搬运工与采石工在河谷会请人施术，以防落石擦伤，但工头担心动作变慢反而误事。城中竞技场管事只允许在训练场使用，正式比试前须经对手同意。港口装卸队若给一名工人单独加护，其他人会要求同等对待，否则认为分配不公。医师提醒泥壳闷汗，伤者裹着它过夜容易发热。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学泥壳厚薄不匀，受术者走几步就觉出僵硬。",
        "熟练后泥壳贴合肩背，抗撞击较稳但仍牵制关节。",
        "再进一步可让泥壳薄一些，减少转身时的迟滞。",
        "高熟练者维持时间更准，仍不防切割，也不增强力量。"
      ]
    },
    {
      "id": "spell_earth_12",
      "theory": "陷足地把魔力渗入湿土颗粒之间，使颗粒暂时失去咬合，土面看上去仍平，踩上去却像稀粥。它只作用于已经含水的软土，干硬地面或碎石路不受影响。施术者无法让土变深，也不能把平地变成泥潭。铺上宽板分散体重，或退出湿土范围，就能避开下陷。",
      "casting": "蹲身以掌根压住湿土，另一手食指在土面画一个螺旋，由内向外转三圈。螺旋画完后，土色微微发暗，下陷感才出现。",
      "failure": "螺旋画反或压得太重，土面会先鼓起一层薄壳，踩上去只留浅脚印，片刻后恢复。施术者若强行补画，可能让边缘干土也变松，使原本安全的落脚点变得不可靠。",
      "counters": [
        "在湿土上铺宽木板，把体重分散到较大面积。",
        "向螺旋中心填入干沙或碎石，可恢复局部咬合。"
      ],
      "socialConsequences": "河谷放牧人用它在自家湿草甸拦走失的牛，邻人若被陷住会要求赔偿弄脏的靴子。城中制革匠担心学徒在浸皮池边乱用，导致工人扭伤。港口理货员最恨有人在货栈通道施术，因为板车陷住会延误装船；港务要求施术者立标提醒，否则按妨碍通行追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学螺旋边缘不清，只有踩中中心才明显下陷。",
        "熟练后下陷区较均匀，仍只限湿软地面。",
        "再进一步可控制范围，使旁边干土不受影响。",
        "高熟练者能更快收束魔力，仍不能把硬地变泥。"
      ]
    }
  ]
}
